INSERT INTO `vocabulary` (`source_language`, `target_language`, `source_word`, `target_word`, `phonetic`, `category`, `example_sentence`) VALUES
('hindi', 'mundari', 'वे भी कमजोर पड़ रहे हैं', 'इनकु कमजोरोःतानाको', 'इनकु कमजोरोःतानाको', 'conversation', 'वे भी कमजोर पड़ रहे हैं -> इनकु कमजोरोःतानाको'),
('hindi', 'mundari', 'इनमें यदि और बढ़ोतरी हो तो और भी अच्छा।', 'नेआको रे ओड़ोःगे सानाडगि होबाजान रे ओड़ोःगे बुगिना।', 'नेआको रे ओड़ोःगे सानाडगि होबाजान रे ओड़ोःगे बुगिना।', 'conversation', 'इनमें यदि और बढ़ोतरी हो तो और भी अच्छा। -> नेआको रे ओड़ोःगे सानाडगि होबाजान रे ओड़ोःगे बुगिना।'),
('hindi', 'mundari', 'उन्होंने शादी करने का भी वादा किया था', 'इनिः आड़ानदि रिका राः किरिआओ जोमलाःए', 'इनिः आड़ानदि रिका राः किरिआओ जोमलाःए', 'conversation', 'उन्होंने शादी करने का भी वादा किया था -> इनिः आड़ानदि रिका राः किरिआओ जोमलाःए'),
('hindi', 'mundari', 'मैं आधे अधूरे पेट उठा तो दूसरी समस्या शुरू।', 'आञ तारा पेरेः लाइः बिरिदकेनाञ दो एटाः बालाए एटेः।', 'आञ तारा पेरेः लाइः बिरिदकेनाञ दो एटाः बालाए एटेः।', 'conversation', 'मैं आधे अधूरे पेट उठा तो दूसरी समस्या शुरू। -> आञ तारा पेरेः लाइः बिरिदकेनाञ दो एटाः बालाए एटेः।'),
('hindi', 'mundari', 'इस सुविधा के कारण इतिहासकार ईश्र्वर हो जाता है।', 'नेआ रानाबाल मेनते इतिहास ओलको बोङगासामको लेकाओःआ', 'नेआ रानाबाल मेनते इतिहास ओलको बोङगासामको लेकाओःआ', 'conversation', 'इस सुविधा के कारण इतिहासकार ईश्र्वर हो जाता है। -> नेआ रानाबाल मेनते इतिहास ओलको बोङगासामको लेकाओःआ'),
('hindi', 'mundari', 'वह पास्ट में सब कुछ खो चुका है।', 'इनिः सिदा रे सोबेनाः आदउतारतादाएः।', 'इनिः सिदा रे सोबेनाः आदउतारतादाएः।', 'conversation', 'वह पास्ट में सब कुछ खो चुका है। -> इनिः सिदा रे सोबेनाः आदउतारतादाएः।'),
('hindi', 'mundari', 'अदिति शायद अब जिंदगी भर यही दोहराती रहेगी।', 'आदिति गोटा जिनिद नेआगे खाने काजिबेड़ाएआएः।', 'आदिति गोटा जिनिद नेआगे खाने काजिबेड़ाएआएः।', 'conversation', 'अदिति शायद अब जिंदगी भर यही दोहराती रहेगी। -> आदिति गोटा जिनिद नेआगे खाने काजिबेड़ाएआएः।'),
('hindi', 'mundari', 'इसलिए वे हमारे दोस्त नहीं हो सकते।', 'नेआ मेनते इनकु आलेआः सोङगे काको बाइ दाड़िओःआ।', 'नेआ मेनते इनकु आलेआः सोङगे काको बाइ दाड़िओःआ।', 'family', 'इसलिए वे हमारे दोस्त नहीं हो सकते। -> नेआ मेनते इनकु आलेआः सोङगे काको बाइ दाड़िओःआ।'),
('hindi', 'mundari', 'और उस दिन ये हवेली हँस रही थी मौज में', 'आर एन हुलाङ एन हवेली लानदातान ताइकेना रासिकाते', 'आर एन हुलाङ एन हवेली लानदातान ताइकेना रासिकाते', 'conversation', 'और उस दिन ये हवेली हँस रही थी मौज में -> आर एन हुलाङ एन हवेली लानदातान ताइकेना रासिकाते'),
('hindi', 'mundari', 'हरेप्रकाश उपाध्याय ने अब तक किया क्या है?', 'हारेप्रकाश उपाध्याय नाआः जाकेद चानाःए चिकातादाएः?', 'हारेप्रकाश उपाध्याय नाआः जाकेद चानाःए चिकातादाएः?', 'conversation', 'हरेप्रकाश उपाध्याय ने अब तक किया क्या है? -> हारेप्रकाश उपाध्याय नाआः जाकेद चानाःए चिकातादाएः?'),
('hindi', 'mundari', 'रात में जहाज हजार द्वारी में लंगर डाल लेता है।', 'निदा जाआज जहार द्वारी रे लाङगार उयुःएआए।', 'निदा जाआज जहार द्वारी रे लाङगार उयुःएआए।', 'conversation', 'रात में जहाज हजार द्वारी में लंगर डाल लेता है। -> निदा जाआज जहार द्वारी रे लाङगार उयुःएआए।'),
('hindi', 'mundari', 'उसी से तो मेरा काम चलता है।', 'एना ते गे आञाः कामि चालाओआ।', 'एना ते गे आञाः कामि चालाओआ।', 'conversation', 'उसी से तो मेरा काम चलता है। -> एना ते गे आञाः कामि चालाओआ।'),
