('hindi', 'mundari', 'दूसरा पहले से आगे निकलना चाहता है।', 'एटाः निः सिदा रे गे आयार सेन सानाङाएः।', 'एटाः निः सिदा रे गे आयार सेन सानाङाएः।', 'conversation', 'दूसरा पहले से आगे निकलना चाहता है। -> एटाः निः सिदा रे गे आयार सेन सानाङाएः।'),
('hindi', 'mundari', 'यूपी इलेक्शन वॉच की सूचना के मुताबिक उत्तर प्रदेश विधान', 'यूपी इलेक्शन वॉच राः उनुदुब होरा ते उत्तर प्रदेश विधान', 'यूपी इलेक्शन वॉच राः उनुदुब होरा ते उत्तर प्रदेश विधान', 'conversation', 'यूपी इलेक्शन वॉच की सूचना के मुताबिक उत्तर प्रदेश विधान -> यूपी इलेक्शन वॉच राः उनुदुब होरा ते उत्तर प्रदेश विधान'),
('hindi', 'mundari', 'तुम्हारे कारण एक बार आईना है आपके', 'आमाः नातिन मोसा आईना मेनाः आमाः', 'आमाः नातिन मोसा आईना मेनाः आमाः', 'conversation', 'तुम्हारे कारण एक बार आईना है आपके -> आमाः नातिन मोसा आईना मेनाः आमाः'),
('hindi', 'mundari', 'यहां कभी भी माओवादी घटना को अंजाम दे सकते हैं।', 'नेताः रे जाआं इमताङो माओवादी ताको जाआन घाटना रिका दाड़िआको।', 'नेताः रे जाआं इमताङो माओवादी ताको जाआन घाटना रिका दाड़िआको।', 'conversation', 'यहां कभी भी माओवादी घटना को अंजाम दे सकते हैं। -> नेताः रे जाआं इमताङो माओवादी ताको जाआन घाटना रिका दाड़िआको।'),
('hindi', 'mundari', 'शीतला को खेद हुआ कि उन्होंने मुझे देख लिया।', 'शीतला गिउःगे टोओर केदाएः चि इनिः आञे लेललिञाएः।', 'शीतला गिउःगे टोओर केदाएः चि इनिः आञे लेललिञाएः।', 'conversation', 'शीतला को खेद हुआ कि उन्होंने मुझे देख लिया। -> शीतला गिउःगे टोओर केदाएः चि इनिः आञे लेललिञाएः।'),
('hindi', 'mundari', 'हमारे दरवाजे तक पहुंच गया है।', 'आलेआः दुआर जाकेद तेबातादा।', 'आलेआः दुआर जाकेद तेबातादा।', 'conversation', 'हमारे दरवाजे तक पहुंच गया है। -> आलेआः दुआर जाकेद तेबातादा।'),
